package kilo

import (
	"bufio"
	"bytes"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
)

const maxTranscriptLine = 10 * 1024 * 1024

// The on-disk transcript is stored as JSONL: exactly one SessionMessage per
// line, in order, with no header line. Entire scopes external-agent
// transcripts by LINE offset (transcript.SliceFromLine) before handing them to
// compact-transcript, so a single-JSON-blob layout would be destroyed by that
// slicing. One-message-per-line keeps line index == message index, which is
// also the unit Entire records via get-transcript-position, so scoping lands on
// message boundaries and header-less slices remain valid JSONL.

// encodeMessagesJSONL serializes messages as one JSON object per line.
func encodeMessagesJSONL(messages []SessionMessage) ([]byte, error) {
	var buf bytes.Buffer
	enc := json.NewEncoder(&buf) // Encode writes directly into buf and appends '\n'.
	for i := range messages {
		if err := enc.Encode(&messages[i]); err != nil {
			return nil, fmt.Errorf("encode message: %w", err)
		}
	}
	return buf.Bytes(), nil
}

// decodeTranscript reads the on-disk transcript, which is always one JSON
// message per line (see encodeMessagesJSONL). Blank/unparseable lines are
// skipped, so header-less scoped slices decode cleanly. Kilo's native session
// export blob is handled separately by parseKiloExport at the ingestion
// boundary — it never reaches disk.
func decodeTranscript(data []byte) ([]SessionMessage, error) {
	messages := make([]SessionMessage, 0)
	scanner := bufio.NewScanner(bytes.NewReader(data))
	scanner.Buffer(make([]byte, 64*1024), maxTranscriptLine)
	for scanner.Scan() {
		line := bytes.TrimSpace(scanner.Bytes())
		if len(line) == 0 {
			continue
		}
		var msg SessionMessage
		if json.Unmarshal(line, &msg) != nil {
			continue
		}
		if msg.Info.ID == "" && msg.Info.Role == "" && len(msg.Parts) == 0 {
			continue
		}
		messages = append(messages, msg)
	}
	if err := scanner.Err(); err != nil {
		return nil, fmt.Errorf("scan kilo transcript: %w", err)
	}
	return messages, nil
}

// parseKiloExport reads Kilo's native session export (a single JSON object with
// a "messages" array) into its messages. Used only when ingesting a fresh
// export from the plugin payload or `kilo session show`; the result is stored
// as JSONL via encodeMessagesJSONL.
func parseKiloExport(raw []byte) ([]SessionMessage, error) {
	trimmed := bytes.TrimSpace(raw)
	if len(trimmed) == 0 {
		return nil, nil
	}
	var export struct {
		Messages []SessionMessage `json:"messages"`
	}
	if err := json.Unmarshal(trimmed, &export); err != nil {
		return nil, fmt.Errorf("parse kilo session export: %w", err)
	}
	return export.Messages, nil
}

// atomicWriteFile writes data to path via a temp file + rename so a crash
// mid-write cannot leave a partially-written transcript behind.
func atomicWriteFile(path string, data []byte, mode os.FileMode) error { //nolint:unparam // Keep permissions configurable for callers needing other file modes.
	dir := filepath.Dir(path)
	tmp, err := os.CreateTemp(dir, ".kilo-write-*")
	if err != nil {
		return err
	}
	tmpName := tmp.Name()
	defer os.Remove(tmpName)
	if err := tmp.Chmod(mode); err != nil {
		return errors.Join(err, tmp.Close())
	}
	if _, err := tmp.Write(data); err != nil {
		return errors.Join(err, tmp.Close())
	}
	if err := tmp.Close(); err != nil {
		return err
	}
	return os.Rename(tmpName, path)
}

package kilo

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"time"

	"github.com/entireio/external-agents/agents/entire-agent-kilo/internal/protocol"
)

// Hook name constants. These are passed as the second positional argument to
// `entire hooks kilo <hook>` by the Kilo plugin. They are intentionally
// kebab-case to match Entire's external-agent hook convention (the dotted
// Kilo native event names like `session.created` are translated by the plugin).
const (
	HookNameSessionStart = "session-start"
	HookNameTurnStart    = "turn-start"
	HookNameTurnEnd      = "turn-end"
	HookNameCompaction   = "compaction"
	HookNameSessionEnd   = "session-end"
)

const (
	pluginDir        = ".kilo/plugins"
	pluginFile       = ".kilo/plugins/entire.ts"
	pluginMarker     = "Auto-generated by `entire enable --agent kilo`"
	transcriptSubdir = "kilo"
)

// sessionInfoRaw is the payload shape for session-start, session-end, and
// compaction hooks. The plugin sends only the session_id; the Kilo session
// JSON is expected to already be on disk (the turn-end hook writes it).
type sessionInfoRaw struct {
	SessionID string `json:"session_id"`
}

// turnStartRaw is the payload for turn-start. Carries the user prompt + model
// captured at message.part.updated time.
type turnStartRaw struct {
	SessionID string `json:"session_id"`
	Prompt    string `json:"prompt"`
	Model     string `json:"model"`
}

// turnEndRaw is the payload for turn-end. Plugin writes the full session JSON
// to session_ref before invoking; the Go binary verifies the file landed and
// emits a TurnEnd event with the model captured at session.status time.
type turnEndRaw struct {
	SessionID string          `json:"session_id"`
	Model     string          `json:"model"`
	Session   json.RawMessage `json:"session,omitempty"`
	Messages  json.RawMessage `json:"messages,omitempty"`
}

func (a *Agent) ParseHook(hookName string, input []byte) (*protocol.EventJSON, error) {
	if len(input) == 0 {
		return nil, nil
	}

	now := time.Now().UTC().Format(time.RFC3339)

	switch hookName {
	case HookNameSessionStart:
		var raw sessionInfoRaw
		if err := json.Unmarshal(input, &raw); err != nil {
			return nil, fmt.Errorf("parse session-start payload: %w", err)
		}
		if raw.SessionID == "" {
			return nil, nil
		}
		return &protocol.EventJSON{
			Type:       1,
			SessionID:  raw.SessionID,
			SessionRef: transcriptPath(raw.SessionID),
			Timestamp:  now,
		}, nil

	case HookNameTurnStart:
		var raw turnStartRaw
		if err := json.Unmarshal(input, &raw); err != nil {
			return nil, fmt.Errorf("parse turn-start payload: %w", err)
		}
		if raw.SessionID == "" {
			return nil, nil
		}
		return &protocol.EventJSON{
			Type:       2,
			SessionID:  raw.SessionID,
			SessionRef: transcriptPath(raw.SessionID),
			Prompt:     raw.Prompt,
			Model:      raw.Model,
			Timestamp:  now,
		}, nil

	case HookNameTurnEnd:
		var raw turnEndRaw
		if err := json.Unmarshal(input, &raw); err != nil {
			return nil, fmt.Errorf("parse turn-end payload: %w", err)
		}
		if raw.SessionID == "" {
			return nil, nil
		}
		sessionRef := transcriptPath(raw.SessionID)
		// Plugin may bundle the session snapshot in the payload (for instances
		// where the plugin can't write to disk itself). Persist it to session_ref
		// so downstream transcript operations see a populated file.
		if len(raw.Session) > 0 || len(raw.Messages) > 0 {
			if err := writeSessionPayload(sessionRef, raw.Session, raw.Messages); err != nil {
				return nil, fmt.Errorf("write session ref on turn-end: %w", err)
			}
		}
		model := raw.Model
		if model == "" {
			model = latestModelFromSessionRef(sessionRef)
		}
		return &protocol.EventJSON{
			Type:       3,
			SessionID:  raw.SessionID,
			SessionRef: sessionRef,
			Model:      model,
			Timestamp:  now,
		}, nil

	case HookNameCompaction:
		var raw sessionInfoRaw
		if err := json.Unmarshal(input, &raw); err != nil {
			return nil, fmt.Errorf("parse compaction payload: %w", err)
		}
		if raw.SessionID == "" {
			return nil, nil
		}
		return &protocol.EventJSON{
			Type:       4,
			SessionID:  raw.SessionID,
			SessionRef: transcriptPath(raw.SessionID),
			Timestamp:  now,
		}, nil

	case HookNameSessionEnd:
		var raw sessionInfoRaw
		if err := json.Unmarshal(input, &raw); err != nil {
			return nil, fmt.Errorf("parse session-end payload: %w", err)
		}
		if raw.SessionID == "" {
			return nil, nil
		}
		return &protocol.EventJSON{
			Type:       5,
			SessionID:  raw.SessionID,
			SessionRef: transcriptPath(raw.SessionID),
			Timestamp:  now,
		}, nil

	default:
		return nil, nil
	}
}

// writeSessionPayload persists the messages from a turn-end hook payload. The
// plugin sends messages in the "messages" field; older/blob payloads may carry
// them inside "session" instead. Stored as one-message-per-line JSONL so
// Entire's line-based transcript scoping lands on message boundaries.
func writeSessionPayload(sessionRef string, sessionRaw, messagesRaw json.RawMessage) error {
	if strings.TrimSpace(sessionRef) == "" {
		return errors.New("session_ref is required")
	}
	if err := os.MkdirAll(filepath.Dir(sessionRef), 0o750); err != nil {
		return err
	}

	var messages []SessionMessage
	switch {
	case len(messagesRaw) > 0:
		if err := json.Unmarshal(messagesRaw, &messages); err != nil {
			return fmt.Errorf("parse messages payload: %w", err)
		}
	case len(sessionRaw) > 0:
		parsed, err := parseKiloExport(sessionRaw)
		if err != nil {
			return err
		}
		messages = parsed
	}

	// Never overwrite an existing transcript with an empty one. A failed
	// snapshot on the plugin side sends messages:[]; clobbering here would
	// destroy the last good transcript. Leave the existing file for
	// prepare-transcript / the next turn to refresh.
	if len(messages) == 0 {
		return nil
	}

	encoded, err := encodeMessagesJSONL(messages)
	if err != nil {
		return fmt.Errorf("encode session: %w", err)
	}
	return atomicWriteFile(sessionRef, encoded, 0o600)
}

// latestModelFromSessionRef returns the most recent assistant model recorded
// in the prepared session JSON at sessionRef.
func latestModelFromSessionRef(sessionRef string) string {
	if strings.TrimSpace(sessionRef) == "" {
		return ""
	}
	data, err := os.ReadFile(sessionRef)
	if err != nil || len(bytes.TrimSpace(data)) == 0 {
		return ""
	}
	messages, err := decodeTranscript(data)
	if err != nil {
		return ""
	}
	return latestSessionModel(messages)
}

func (a *Agent) InstallHooks(localDev bool, force bool) (int, error) {
	root := protocol.RepoRoot()

	cmdPrefix := "entire"
	if localDev {
		cmdPrefix = `go run "$(git rev-parse --show-toplevel)"/cmd/entire/main.go`
	}
	content := strings.ReplaceAll(generatePlugin(), entireCmdPlaceholder, cmdPrefix)

	path := filepath.Join(root, pluginFile)
	if info, lstatErr := os.Lstat(path); lstatErr == nil {
		// Replacing a directory would require deleting potentially user-owned
		// data. Force only permits replacing other directory entries.
		if info.IsDir() {
			return 0, fmt.Errorf("refusing to replace kilo plugin directory %s; move or remove the directory before installing", path)
		}
		// A forced install replaces symlinks and other non-regular entries
		// atomically rather than writing through them.
		if !info.Mode().IsRegular() {
			if !force {
				return 0, fmt.Errorf("refusing to overwrite non-regular kilo plugin %s; pass force to replace it", path)
			}
		} else if existing, readErr := os.ReadFile(path); readErr == nil {
			// Force is intentionally allowed to rewrite identical content so it
			// can repair file metadata such as permissions.
			if string(existing) == content && !force {
				return 0, nil
			}
			// Protect user-owned or third-party Kilo plugins from being silently
			// overwritten by the generated Entire plugin. Only an explicit force
			// install may replace a foreign plugin file, matching the ownership
			// contract used by the omp adapter.
			if !isOwnedPlugin(existing) && !force {
				return 0, fmt.Errorf("refusing to overwrite foreign kilo plugin %s; pass force to replace it", path)
			}
		} else if !force {
			return 0, readErr
		}
	} else if !os.IsNotExist(lstatErr) {
		return 0, lstatErr
	}

	dir := filepath.Join(root, pluginDir)
	if err := os.MkdirAll(dir, 0o750); err != nil {
		return 0, fmt.Errorf("create plugin dir: %w", err)
	}
	if err := atomicWriteFile(path, []byte(content), 0o600); err != nil {
		return 0, fmt.Errorf("write plugin: %w", err)
	}

	return 1, nil
}

func (a *Agent) UninstallHooks() error {
	root := protocol.RepoRoot()
	path := filepath.Join(root, pluginFile)

	// Stat follows links only to inspect ownership of regular-file targets.
	// Remove below unlinks path itself, preserving any symlink target.
	info, err := os.Stat(path)
	if os.IsNotExist(err) {
		return nil
	}
	if err != nil {
		return err
	}
	if !info.Mode().IsRegular() {
		return nil
	}
	existing, err := os.ReadFile(path)
	if err != nil {
		return err
	}
	if !isOwnedPlugin(existing) {
		return nil
	}

	if err := os.Remove(path); err != nil && !os.IsNotExist(err) {
		return err
	}
	dir := filepath.Join(root, pluginDir)
	if entries, err := os.ReadDir(dir); err == nil && len(entries) == 0 {
		_ = os.Remove(dir)
	}
	kiloDir := filepath.Join(root, ".kilo")
	if entries, err := os.ReadDir(kiloDir); err == nil && len(entries) == 0 {
		_ = os.Remove(kiloDir)
	}
	return nil
}

func isOwnedPlugin(data []byte) bool {
	return strings.Contains(string(data), pluginMarker)
}

func (a *Agent) AreHooksInstalled() bool {
	// Installation detection must include plugins disabled by KILO_PURE so
	// Entire's uninstall sweep can still discover and remove them.
	root := protocol.RepoRoot()
	path := filepath.Join(root, pluginFile)
	info, err := os.Stat(path)
	if err != nil || !info.Mode().IsRegular() {
		return false
	}
	data, err := os.ReadFile(path)
	return err == nil && isOwnedPlugin(data)
}

// fetchSession is reserved for mid-turn refresh from the Kilo HTTP server.
// Kilo's CLI does not currently expose a `kilo export` equivalent, so the
// production transcript path is the plugin write-on-turn-end. This method
// remains as a future hook for a Bun-based refresh subprocess.
func (a *Agent) fetchSession(sessionID, sessionRef string) error {
	if strings.TrimSpace(sessionID) == "" || strings.TrimSpace(sessionRef) == "" {
		return errors.New("session id and session ref are required")
	}
	runner := a.CommandRunner
	if runner == nil {
		runner = &DefaultCommandRunner{}
	}
	if err := os.MkdirAll(filepath.Dir(sessionRef), 0o750); err != nil {
		return err
	}
	ctx, cancel := context.WithTimeout(context.Background(), prepareTranscriptTimeout)
	defer cancel()

	// Export Kilo's native session blob and store it as one-message-per-line
	// JSONL so downstream scoping works (session_jsonl.go).
	raw, err := runner.ExportSession(ctx, sessionID)
	if err != nil {
		return err
	}
	messages, err := parseKiloExport(raw)
	if err != nil {
		return err
	}
	encoded, err := encodeMessagesJSONL(messages)
	if err != nil {
		return err
	}
	return atomicWriteFile(sessionRef, encoded, 0o600)
}

const entireCmdPlaceholder = "__ENTIRE_CMD__"

func generatePlugin() string {
	return `// Entire CLI plugin for Kilo Code
// ` + pluginMarker + `
// Do not edit manually — changes will be overwritten on next install.
// Requires Bun runtime (used by Kilo's plugin system for loading ESM plugins).
import type { Plugin } from "@kilocode/plugin"

export const EntirePlugin: Plugin = async ({ directory }) => {
  const ENTIRE_CMD = '__ENTIRE_CMD__'
  const seenUserMessages = new Set<string>()
  let currentSessionID: string | null = null
  let currentModel: string | null = null
  const messageStore = new Map<string, any>()
  const announcedSessions = new Set<string>()

  function hookCmd(hookName: string): string[] {
    if (ENTIRE_CMD !== "entire") {
      return ["sh", "-c", ` + "`${ENTIRE_CMD} hooks kilo ${hookName}`" + `]
    }
    return ["sh", "-c", ` + "`if ! command -v entire >/dev/null 2>&1; then exit 0; fi; exec entire hooks kilo ${hookName}`" + `]
  }

  async function callHook(hookName: string, payload: Record<string, unknown>) {
    try {
      const json = JSON.stringify(payload)
      const proc = Bun.spawn(hookCmd(hookName), {
        cwd: directory,
        stdin: new Blob([json + "\n"]),
        stdout: "ignore",
        stderr: "ignore",
      })
      await proc.exited
    } catch {
      // Silently ignore — plugin failures must not crash Kilo.
    }
  }

  function callHookSync(hookName: string, payload: Record<string, unknown>) {
    try {
      const json = JSON.stringify(payload)
      Bun.spawnSync(hookCmd(hookName), {
        cwd: directory,
        stdin: new TextEncoder().encode(json + "\n"),
        stdout: "ignore",
        stderr: "ignore",
      })
    } catch {
      // Silently ignore — plugin failures must not crash Kilo.
    }
  }

  function resetSessionTracking(sessionID: string) {
    if (currentSessionID === sessionID) {
      return false
    }
    seenUserMessages.clear()
    messageStore.clear()
    currentModel = null
    currentSessionID = sessionID
    return true
  }

  return {
    event: async ({ event }) => {
      try {
        switch (event.type) {
          case "session.created": {
            const session = (event as any).properties?.info
            if (!session?.id) break
            // Sub-sessions are tracked by Kilo too; only top-level ones get an
            // Entire SessionStart.
            if (session.parentID) break
            if (announcedSessions.has(session.id)) break
            announcedSessions.add(session.id)
            if (resetSessionTracking(session.id)) {
              callHookSync("session-start", { session_id: session.id })
            }
            break
          }

          case "message.updated": {
            const msg = (event as any).properties?.info
            if (!msg) break
            if (msg.sessionID && resetSessionTracking(msg.sessionID) && !announcedSessions.has(msg.sessionID)) {
              announcedSessions.add(msg.sessionID)
              callHookSync("session-start", { session_id: msg.sessionID })
            }
            messageStore.set(msg.id, msg)
            if (msg.role === "assistant" && msg.modelID) {
              currentModel = msg.modelID
            }
            // Turn-start fires from the text part (message.part.updated), which
            // carries the actual prompt. Firing here with an empty prompt would
            // mark the message seen and suppress the real one, dropping prompts.
            break
          }

          case "message.part.updated": {
            const part = (event as any).properties?.part
            if (!part?.messageID) break
            const msg = messageStore.get(part.messageID)
            if (msg?.role === "user" && part.type === "text" && !seenUserMessages.has(msg.id)) {
              seenUserMessages.add(msg.id)
              const sessionID = msg.sessionID ?? currentSessionID
              if (sessionID) {
                callHookSync("turn-start", {
                  session_id: sessionID,
                  prompt: part.text ?? "",
                  model: currentModel ?? "",
                })
              }
            }
            break
          }

          case "session.status": {
            // session.status fires reliably in both TUI and ` + "`kilo run`" + ` mode.
            // session.idle is deprecated upstream and not always emitted on run exit.
            const props = (event as any).properties
            if (props?.status?.type !== "idle") break
            const sessionID = props?.sessionID ?? currentSessionID
            if (!sessionID) break
            // Fire turn-end synchronously — kilo run exits on this same idle
            // event, so an awaited async fetch here can be cancelled before the
            // hook runs. Entire materializes the transcript on its side via
            // prepare-transcript (kilo session show), which reads Kilo's
            // persisted store and is authoritative regardless of process exit.
            callHookSync("turn-end", {
              session_id: sessionID,
              model: currentModel ?? "",
            })
            break
          }

          case "session.compacted": {
            const sessionID = (event as any).properties?.sessionID
            if (!sessionID) break
            await callHook("compaction", { session_id: sessionID })
            break
          }

          case "session.deleted": {
            const session = (event as any).properties?.info
            if (!session?.id) break
            seenUserMessages.clear()
            messageStore.clear()
            announcedSessions.delete(session.id)
            currentSessionID = null
            callHookSync("session-end", { session_id: session.id })
            break
          }

          case "server.instance.disposed": {
            // Fires on Kilo shutdown (TUI close or ` + "`kilo run`" + ` exit).
            // session.deleted only fires on explicit user deletion, so this is
            // the only reliable terminator on process exit.
            if (!currentSessionID) break
            const sessionID = currentSessionID
            seenUserMessages.clear()
            messageStore.clear()
            announcedSessions.delete(sessionID)
            currentSessionID = null
            callHookSync("session-end", { session_id: sessionID })
            break
          }
        }
      } catch {
        // Silently ignore — plugin failures must not crash Kilo.
      }
    },
  }
}

export default { id: "entire-agent-kilo", server: EntirePlugin }
`
}

func transcriptPath(sessionID string) string {
	return filepath.Join(protocol.DefaultSessionDir(protocol.RepoRoot()), transcriptSubdir, safeSessionID(sessionID)+".json")
}

package kilo

import (
	"encoding/json"
	"errors"
	"fmt"
	"net/url"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"time"

	"github.com/entireio/external-agents/agents/entire-agent-kilo/internal/protocol"
)

const prepareTranscriptTimeout = 30 * time.Second

// sessionIDFromTranscriptData extracts the session id from a stored transcript.
// Returns ("", nil) when it is empty or carries no session id — callers treat
// that as a graceful no-op (nothing to refresh from).
func sessionIDFromTranscriptData(data []byte) (string, error) {
	messages, err := decodeTranscript(data)
	if err != nil {
		return "", err
	}
	return sessionIDFromMessages(messages), nil
}

func (a *Agent) ReadSession(input *protocol.HookInputJSON) (protocol.AgentSessionJSON, error) {
	var sessionID string
	var sessionRef string
	if input != nil {
		sessionID = input.SessionID
		sessionRef = input.SessionRef
		if sessionRef == "" && sessionID != "" {
			sessionRef = transcriptPath(sessionID)
		}
	}
	if sessionRef == "" {
		return protocol.AgentSessionJSON{}, errors.New("session_ref or session_id is required")
	}

	data, err := os.ReadFile(sessionRef)
	if err != nil {
		return protocol.AgentSessionJSON{}, err
	}
	messages, err := decodeTranscript(data)
	if err != nil {
		return protocol.AgentSessionJSON{}, err
	}

	// The JSONL layout carries no session header, so recover the id from the
	// hook input, the messages, or the file name (in that order).
	if sessionID == "" {
		sessionID = sessionIDFromMessages(messages)
	}
	if sessionID == "" {
		sessionID = strings.TrimSuffix(filepath.Base(sessionRef), filepath.Ext(sessionRef))
	}

	return protocol.AgentSessionJSON{
		SessionID:     sessionID,
		AgentName:     "kilo",
		RepoPath:      protocol.RepoRoot(),
		SessionRef:    sessionRef,
		StartTime:     startTimeFromMessages(messages).Format(time.RFC3339),
		NativeData:    data,
		ModifiedFiles: modifiedFilesFromMessages(messages),
		NewFiles:      []string{},
		DeletedFiles:  []string{},
	}, nil
}

// sessionIDFromMessages returns the first non-empty sessionID recorded on a
// message's info (the JSONL layout has no session header line).
func sessionIDFromMessages(messages []SessionMessage) string {
	for _, msg := range messages {
		if id := strings.TrimSpace(msg.Info.SessionID); id != "" {
			return id
		}
	}
	return ""
}

// startTimeFromMessages returns the earliest message creation time, or now.
func startTimeFromMessages(messages []SessionMessage) time.Time {
	for _, msg := range messages {
		if msg.Info.Time != nil {
			if t := msg.Info.Time.Created.Time(); !t.IsZero() {
				return t
			}
		}
	}
	return time.Now().UTC()
}

func (a *Agent) PrepareTranscript(sessionRef string) error {
	if strings.TrimSpace(sessionRef) == "" {
		return errors.New("session_ref is required")
	}
	data, err := os.ReadFile(sessionRef)
	if err != nil {
		return fmt.Errorf("read transcript for prepare: %w", err)
	}
	sessionID, err := sessionIDFromTranscriptData(data)
	if err != nil {
		return err
	}
	if sessionID == "" {
		return nil
	}
	return a.fetchSession(sessionID, sessionRef)
}

func (a *Agent) WriteSession(session protocol.AgentSessionJSON) error {
	if session.SessionRef == "" {
		return errors.New("session_ref is required")
	}
	if err := os.MkdirAll(filepath.Dir(session.SessionRef), 0o700); err != nil {
		return err
	}
	return atomicWriteFile(session.SessionRef, session.NativeData, 0o600)
}

func (a *Agent) ReadTranscript(sessionRef string) ([]byte, error) {
	data, err := os.ReadFile(sessionRef)
	if err != nil {
		return nil, err
	}
	if _, err := decodeTranscript(data); err != nil {
		return nil, err
	}
	return data, nil
}

func (a *Agent) ChunkTranscript(content []byte, maxSize int) ([][]byte, error) {
	if maxSize <= 0 {
		return nil, fmt.Errorf("max-size must be positive, got %d", maxSize)
	}
	var chunks [][]byte
	for len(content) > 0 {
		end := min(maxSize, len(content))
		chunks = append(chunks, content[:end])
		content = content[end:]
	}
	return chunks, nil
}

func (a *Agent) ReassembleTranscript(chunks [][]byte) ([]byte, error) {
	var data []byte
	for _, chunk := range chunks {
		data = append(data, chunk...)
	}
	return data, nil
}

func (a *Agent) GetTranscriptPosition(path string) (int, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		if os.IsNotExist(err) {
			return 0, nil
		}
		return 0, err
	}
	messages, err := decodeTranscript(data)
	if err != nil {
		return 0, err
	}
	return len(messages), nil
}

func (a *Agent) ExtractModifiedFiles(path string, offset int) ([]string, int, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, 0, err
	}
	messages, err := decodeTranscript(data)
	if err != nil {
		return nil, 0, err
	}
	return modifiedFilesFromMessages(messagesFromOffset(messages, offset)), len(messages), nil
}

func (a *Agent) ExtractPrompts(sessionRef string, offset int) ([]string, error) {
	data, err := os.ReadFile(sessionRef)
	if err != nil {
		return nil, err
	}
	messages, err := decodeTranscript(data)
	if err != nil {
		return nil, err
	}
	var prompts []string
	for _, msg := range messagesFromOffset(messages, offset) {
		if msg.Info.Role != MessageRoleUser {
			continue
		}
		if text := messageText(msg); text != "" {
			prompts = append(prompts, text)
		}
	}
	return prompts, nil
}

func (a *Agent) ExtractSummary(sessionRef string) (string, bool, error) {
	data, err := os.ReadFile(sessionRef)
	if err != nil {
		return "", false, err
	}
	messages, err := decodeTranscript(data)
	if err != nil {
		return "", false, err
	}
	for i := len(messages) - 1; i >= 0; i-- {
		msg := messages[i]
		if msg.Info.Role != MessageRoleAssistant {
			continue
		}
		if text := messageText(msg); text != "" {
			return text, true, nil
		}
	}
	return "", false, nil
}

func (a *Agent) CalculateTokens(data []byte, offset int) (protocol.TokenUsageResponse, error) {
	messages, err := decodeTranscript(data)
	if err != nil {
		return protocol.TokenUsageResponse{}, err
	}
	var usage protocol.TokenUsageResponse
	for _, msg := range messagesFromOffset(messages, offset) {
		if msg.Info.Role != MessageRoleAssistant || msg.Info.Tokens == nil {
			continue
		}
		tokens := msg.Info.Tokens
		usage.InputTokens += tokens.Input
		usage.OutputTokens += tokens.Output
		if tokens.Cache != nil {
			usage.CacheReadTokens += tokens.Cache.Read
			usage.CacheCreationTokens += tokens.Cache.Write
		}
		usage.APICallCount++
	}
	return usage, nil
}

// messagesFromOffset returns the messages at index >= offset. Because the
// on-disk transcript is one message per line, the offset Entire records via
// get-transcript-position (a line index) is also a message index.
func messagesFromOffset(messages []SessionMessage, offset int) []SessionMessage {
	if len(messages) == 0 {
		return nil
	}
	if offset < 0 {
		offset = 0
	}
	if offset >= len(messages) {
		return nil
	}
	return messages[offset:]
}

func latestSessionModel(messages []SessionMessage) string {
	for i := len(messages) - 1; i >= 0; i-- {
		info := messages[i].Info
		if info.Role != MessageRoleAssistant {
			continue
		}
		if model := strings.TrimSpace(info.ModelID); model != "" {
			return model
		}
	}
	return ""
}

func modifiedFilesFromMessages(messages []SessionMessage) []string {
	seen := map[string]bool{}
	for _, msg := range messages {
		for _, file := range modifiedFilesFromMessage(msg) {
			if file != "" {
				seen[file] = true
			}
		}
	}
	files := make([]string, 0, len(seen))
	for file := range seen {
		files = append(files, file)
	}
	sort.Strings(files)
	return files
}

// toolInputFileKeys lists the JSON object keys to scan on a tool call's
// `state.input` for file paths. Includes single-path and multi-path forms.
var toolInputFileKeys = []string{"path", "filePath", "filepath", "file", "absolutePath", "paths", "files"}

// toolMetadataFileKeys lists the JSON object keys to scan on a tool call's
// `state.metadata` (Kilo wraps the resolved path here for write/edit tools).
var toolMetadataFileKeys = []string{"filePath", "filepath", "path", "absolutePath"}

func modifiedFilesFromMessage(msg SessionMessage) []string {
	var files []string
	for _, part := range msg.Parts {
		if part.Type != PartTool || part.State == nil || !isMutatingToolName(part.Tool) {
			continue
		}
		files = append(files, filePathsFromJSON(part.State.Input, toolInputFileKeys)...)
		files = append(files, filePathsFromJSON(part.State.Metadata, toolMetadataFileKeys)...)
	}
	return cleanFiles(files)
}

func filePathsFromJSON(raw json.RawMessage, keys []string) []string {
	if len(raw) == 0 {
		return nil
	}
	var obj map[string]json.RawMessage
	if err := json.Unmarshal(raw, &obj); err != nil {
		return nil
	}
	var files []string
	for _, key := range keys {
		files = append(files, stringValues(obj[key])...)
	}
	return files
}

func stringValues(raw json.RawMessage) []string {
	if len(raw) == 0 {
		return nil
	}
	var s string
	if err := json.Unmarshal(raw, &s); err == nil {
		return []string{s}
	}
	var arr []string
	if err := json.Unmarshal(raw, &arr); err == nil {
		return arr
	}
	return nil
}

func cleanFiles(files []string) []string {
	out := files[:0]
	for _, file := range files {
		file = cleanFile(file)
		if file != "" {
			out = append(out, file)
		}
	}
	return out
}

func cleanFile(file string) string {
	file = strings.TrimSpace(file)
	if file == "" {
		return ""
	}
	if u, err := url.Parse(file); err == nil && u.Scheme == "file" {
		file = u.Path
		if unescaped, err := url.PathUnescape(file); err == nil {
			file = unescaped
		}
	}
	return file
}

func isMutatingToolName(name string) bool {
	switch normalizeToolName(name) {
	case "write", "edit", "multiedit", "multi_edit",
		"patch", "create", "create_file",
		"delete", "delete_file",
		"move", "move_file",
		"rename", "rename_file":
		return true
	}
	return false
}

func normalizeToolName(name string) string {
	return strings.ReplaceAll(strings.ToLower(strings.TrimSpace(name)), "-", "_")
}

func messageText(msg SessionMessage) string {
	var parts []string
	for _, part := range msg.Parts {
		if part.Type == PartText && part.Text != "" {
			parts = append(parts, part.Text)
		}
	}
	return strings.Join(parts, "\n")
}

func messageTimestamp(msg SessionMessage) string {
	if msg.Info.Time == nil {
		return ""
	}
	if t := msg.Info.Time.Created.Time(); !t.IsZero() {
		return t.Format(time.RFC3339)
	}
	return ""
}
package kilo

import (
	"bytes"
	"encoding/base64"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"strings"

	"github.com/entireio/external-agents/agents/entire-agent-kilo/internal/protocol"
)

const (
	compactTranscriptAgent      = "kilo"
	compactTranscriptCLIVersion = "unknown"
)

type compactTranscriptLine struct {
	V            int    `json:"v"`
	Agent        string `json:"agent"`
	CLIVersion   string `json:"cli_version"`
	Type         string `json:"type"`
	TS           string `json:"ts,omitempty"`
	ID           string `json:"id,omitempty"`
	InputTokens  int    `json:"input_tokens,omitempty"`
	OutputTokens int    `json:"output_tokens,omitempty"`
	Content      any    `json:"content"`
}

type compactUserTextBlock struct {
	Text string `json:"text"`
}

type compactAssistantTextBlock struct {
	Type string `json:"type"`
	Text string `json:"text"`
}

type compactAssistantToolUseBlock struct {
	Type   string                 `json:"type"`
	ID     string                 `json:"id,omitempty"`
	Name   string                 `json:"name"`
	Input  any                    `json:"input"`
	Result *compactToolResultJSON `json:"result,omitempty"`
}

type compactToolResultJSON struct {
	Output string `json:"output"`
	Status string `json:"status"`
}

func (a *Agent) CompactTranscript(sessionRef string) (protocol.CompactTranscriptResponse, error) {
	data, err := os.ReadFile(sessionRef)
	if err != nil {
		return protocol.CompactTranscriptResponse{}, fmt.Errorf("failed to read transcript: %w", err)
	}
	compacted, err := compactTranscriptBytes(data)
	if err != nil {
		return protocol.CompactTranscriptResponse{}, err
	}
	return protocol.CompactTranscriptResponse{Transcript: base64.StdEncoding.EncodeToString(compacted)}, nil
}

func compactTranscriptBytes(data []byte) ([]byte, error) {
	messages, err := decodeTranscript(data)
	if err != nil {
		return nil, err
	}
	if len(messages) == 0 {
		return nil, errors.New("compact transcript produced no output")
	}

	cliVersion := compactCLIVersion()
	var buf bytes.Buffer
	for _, msg := range messages {
		switch msg.Info.Role {
		case MessageRoleUser:
			content := compactUserContent(msg.Parts)
			if len(content) == 0 {
				continue
			}
			if err := writeCompactTranscriptLine(&buf, compactTranscriptLine{
				V:          1,
				Agent:      compactTranscriptAgent,
				CLIVersion: cliVersion,
				Type:       "user",
				TS:         messageTimestamp(msg),
				Content:    content,
			}); err != nil {
				return nil, err
			}
		case MessageRoleAssistant:
			content := compactAssistantContent(msg.Parts)
			if len(content) == 0 {
				continue
			}
			line := compactTranscriptLine{
				V:          1,
				Agent:      compactTranscriptAgent,
				CLIVersion: cliVersion,
				Type:       "assistant",
				TS:         messageTimestamp(msg),
				ID:         msg.Info.ID,
				Content:    content,
			}
			if msg.Info.Tokens != nil {
				line.InputTokens = msg.Info.Tokens.Input
				line.OutputTokens = msg.Info.Tokens.Output
			}
			if err := writeCompactTranscriptLine(&buf, line); err != nil {
				return nil, err
			}
		}
	}
	if buf.Len() == 0 {
		return nil, errors.New("compact transcript produced no output")
	}
	return buf.Bytes(), nil
}

func compactUserContent(parts []MessagePart) []compactUserTextBlock {
	out := make([]compactUserTextBlock, 0, len(parts))
	for _, part := range parts {
		if part.Type == PartText && part.Text != "" {
			out = append(out, compactUserTextBlock{Text: part.Text})
		}
	}
	return out
}

func compactAssistantContent(parts []MessagePart) []any {
	out := make([]any, 0, len(parts))
	for _, part := range parts {
		switch part.Type {
		case PartText:
			if part.Text != "" {
				out = append(out, compactAssistantTextBlock{Type: "text", Text: part.Text})
			}
		case PartTool:
			tool := compactAssistantToolUseBlock{
				Type:  "tool_use",
				ID:    part.CallID,
				Name:  part.Tool,
				Input: decodeRawInput(part.State),
			}
			if result := toolResultFromState(part.State); result != nil {
				tool.Result = result
			}
			out = append(out, tool)
		case PartReasoning, PartFile, PartSubtask:
			// Reasoning (thinking), file attachments, and subtask markers are not
			// represented in the compact transcript. Dropping reasoning also means
			// no provider thinking signature is ever emitted.
		}
	}
	return out
}

func decodeRawInput(state *ToolState) any {
	if state == nil || len(state.Input) == 0 {
		return map[string]any{}
	}
	var decoded any
	if err := json.Unmarshal(state.Input, &decoded); err != nil {
		return string(state.Input)
	}
	return decoded
}

func toolResultFromState(state *ToolState) *compactToolResultJSON {
	if state == nil {
		return nil
	}
	if state.Output == "" && state.Error == "" {
		return nil
	}
	status := "success"
	output := state.Output
	if state.Error != "" || strings.EqualFold(state.Status, "error") {
		status = "error"
		if output == "" {
			output = state.Error
		}
	}
	return &compactToolResultJSON{Output: output, Status: status}
}

func writeCompactTranscriptLine(buf *bytes.Buffer, line compactTranscriptLine) error {
	encoded, err := json.Marshal(line)
	if err != nil {
		return err
	}
	buf.Write(encoded)
	return buf.WriteByte('\n')
}

func compactCLIVersion() string {
	if version := strings.TrimSpace(os.Getenv("ENTIRE_CLI_VERSION")); version != "" {
		return version
	}
	return compactTranscriptCLIVersion
}

