package vibe

import (
	"os"
	"os/exec"
	"path/filepath"
	"strings"

	"github.com/entireio/external-agents/agents/entire-agent-mistral-vibe/internal/protocol"
)

const agentName = "mistral-vibe"

type Agent struct {
	// Fetcher reads a session from Vibe. Tests substitute their own.
	Fetcher SessionFetcher
}

func New() *Agent {
	return &Agent{Fetcher: &AppServerFetcher{}}
}

func (a *Agent) Info() protocol.InfoResponse {
	return protocol.InfoResponse{
		ProtocolVersion: protocol.ProtocolVersion,
		Name:            agentName,
		Type:            "Mistral Vibe",
		Description:     "Mistral Vibe coding agent integration for Entire",
		IsPreview:       true,
		ProtectedDirs:   []string{".vibe"},
		HookNames: []string{
			HookNameSessionStart,
			HookNamePreAgent,
			HookNameNotification,
			HookNameSessionEnd,
		},
		Capabilities: protocol.DeclaredCapabilities{
			Hooks:              true,
			TranscriptAnalyzer: true,
			TranscriptPreparer: true,
			TokenCalculator:    true,
			CompactTranscript:  true,
			UsesTerminal:       true,
		},
	}
}

func (a *Agent) Detect() protocol.DetectResponse {
	if _, err := exec.LookPath("vibe"); err == nil {
		return protocol.DetectResponse{Present: true}
	}
	info, err := os.Stat(filepath.Join(protocol.RepoRoot(), ".vibe"))
	return protocol.DetectResponse{Present: err == nil && info.IsDir()}
}

func (a *Agent) GetSessionID(input *protocol.HookInputJSON) string {
	if input != nil {
		return input.SessionID
	}
	return ""
}

func (a *Agent) FormatResumeCommand(sessionID string) string {
	if sessionID == "" {
		return "vibe --continue"
	}
	return "vibe --resume " + shellQuote(sessionID)
}

// shellQuote returns value unchanged when it only contains characters safe to
// pass through a shell verbatim; otherwise it single-quotes it. The resume
// command is a display/exec string, so a hostile session id must not be able to
// inject shell syntax.
func shellQuote(value string) string {
	for _, r := range value {
		if !isSafeResumeRune(r) {
			return "'" + strings.ReplaceAll(value, "'", "'\\''") + "'"
		}
	}
	return value
}

func isSafeResumeRune(r rune) bool {
	return r == '-' || r == '_' || r == '.' || r == ':' || r == '/' ||
		(r >= '0' && r <= '9') || (r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z')
}

package vibe

import (
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"os"
	"path/filepath"
	"regexp"
	"strings"

	"github.com/entireio/external-agents/agents/entire-agent-mistral-vibe/internal/protocol"
)

const (
	transcriptSubdir = "mistral-vibe"
	transcriptExt    = ".jsonl"
	stateExt         = ".state.json"
)

func (a *Agent) GetSessionDir(repoPath string) (string, error) {
	return filepath.Join(protocol.DefaultSessionDir(repoPath), transcriptSubdir), nil
}

var sessionIDPathSanitizer = regexp.MustCompile(`[^A-Za-z0-9_.-]+`)

// safeSessionID preserves non-device IDs made only of A-Za-z0-9_.-. Other IDs
// use a reserved prefix plus a stable hash, so transformed IDs cannot collide
// with unchanged IDs or collapse onto one another. Dots are safe because
// callers append a filename extension, so "." and ".." cannot become path
// segments. Vibe session IDs are UUIDs and pass through unchanged.
func safeSessionID(sessionID string) string {
	safeID := sessionIDPathSanitizer.ReplaceAllString(sessionID, "_")
	if safeID != "" && safeID == sessionID && !isWindowsDeviceName(sessionID) {
		return safeID
	}
	sum := sha256.Sum256([]byte(sessionID))
	return "~" + hex.EncodeToString(sum[:16])
}

func (a *Agent) ResolveSessionFile(sessionDir, sessionID string) string {
	return filepath.Join(sessionDir, safeSessionID(sessionID)+transcriptExt)
}

func transcriptPath(sessionID string) string {
	return filepath.Join(protocol.DefaultSessionDir(protocol.RepoRoot()), transcriptSubdir, safeSessionID(sessionID)+transcriptExt)
}

// sessionState is what the hooks learn about a session that a later
// prepare-transcript needs: that call can come from a git hook, which has
// neither the hook payload nor Vibe's environment.
type sessionState struct {
	SessionID    string `json:"session_id"`
	VibeHome     string `json:"vibe_home,omitempty"`
	AppServerBin string `json:"app_server_bin,omitempty"`
	Model        string `json:"model,omitempty"`
}

// statePathFor returns the state file that sits next to a transcript file.
func statePathFor(sessionRef string) string {
	return strings.TrimSuffix(sessionRef, transcriptExt) + stateExt
}

func loadState(sessionRef string) sessionState {
	var state sessionState
	data, err := os.ReadFile(statePathFor(sessionRef))
	if err != nil {
		return state
	}
	_ = json.Unmarshal(data, &state)
	return state
}

func saveState(sessionRef string, state sessionState) error {
	data, err := json.Marshal(state)
	if err != nil {
		return err
	}
	if err := os.MkdirAll(filepath.Dir(sessionRef), 0o750); err != nil {
		return err
	}
	return atomicWriteFile(statePathFor(sessionRef), data, 0o600)
}

package vibe

import (
	"encoding/json"
	"time"
)

// Entry types in Vibe's public session history
// (vibe.public-session-state/v1, read through vibe-app-server).
const (
	EntryMessage   = "message"
	EntryReasoning = "reasoning"
	EntryEffect    = "effect"
	EntryNotice    = "notice"

	RoleUser      = "user"
	RoleAssistant = "assistant"
)

// Entry is one line of the stored transcript: a Vibe history entry, plus an
// optional token snapshot Entire adds when it stores the line.
type Entry struct {
	ID        string         `json:"id"`
	SessionID string         `json:"sessionId,omitempty"`
	TurnID    string         `json:"turnId,omitempty"`
	CreatedAt int64          `json:"createdAt,omitempty"`
	Type      string         `json:"type"`
	Role      string         `json:"role,omitempty"`
	Content   []ContentBlock `json:"content,omitempty"`
	Text      string         `json:"text,omitempty"`
	Title     string         `json:"title,omitempty"`
	Detail    *EffectDetail  `json:"detail,omitempty"`
	State     *EffectState   `json:"state,omitempty"`

	// Usage is the session's cumulative token usage when this line was the
	// last one stored. Only the last line of each refresh carries it.
	Usage *TokenUsage `json:"entireUsage,omitempty"`
}

type ContentBlock struct {
	Type string `json:"type"`
	Text string `json:"text,omitempty"`
}

// EffectDetail describes a tool call. Notices reuse the "detail" key with a
// different shape, which is why every field here is optional.
type EffectDetail struct {
	ToolName string          `json:"toolName,omitempty"`
	Kind     string          `json:"kind,omitempty"`
	Input    json.RawMessage `json:"input,omitempty"`
}

type EffectState struct {
	Status     string          `json:"status,omitempty"`
	Output     json.RawMessage `json:"output,omitempty"`
	OutputText string          `json:"outputText,omitempty"`
	Error      json.RawMessage `json:"error,omitempty"`
}

// TokenUsage mirrors the session's tokenUsage object. InputTokens includes the
// cached tokens.
type TokenUsage struct {
	InputTokens       int `json:"inputTokens"`
	OutputTokens      int `json:"outputTokens"`
	TotalTokens       int `json:"totalTokens,omitempty"`
	CachedInputTokens int `json:"cachedInputTokens,omitempty"`
}

func (e Entry) createdTime() time.Time {
	if e.CreatedAt == 0 {
		return time.Time{}
	}
	return time.UnixMilli(e.CreatedAt).UTC()
}

// text returns the joined text blocks of a message entry.
func (e Entry) text() string {
	var out string
	for _, block := range e.Content {
		if block.Type != "text" || block.Text == "" {
			continue
		}
		if out != "" {
			out += "\n"
		}
		out += block.Text
	}
	return out
}

package vibe

import (
	"bufio"
	"bytes"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
)

const maxTranscriptLine = 10 * 1024 * 1024

// The stored transcript is JSONL: one Vibe history entry per line, in order,
// with no header. Entire scopes external-agent transcripts by line offset
// before handing them to compact-transcript, so line index must equal entry
// index, and a slice that starts mid-file must still decode.

// encodeLines joins already-encoded entries, one per line.
func encodeLines(lines []json.RawMessage) []byte {
	var buf bytes.Buffer
	for _, line := range lines {
		buf.Write(bytes.TrimSpace(line))
		buf.WriteByte('\n')
	}
	return buf.Bytes()
}

// decodeTranscript reads the stored transcript. Blank and unparseable lines are
// skipped so that a scoped slice decodes cleanly.
func decodeTranscript(data []byte) ([]Entry, error) {
	entries := make([]Entry, 0)
	scanner := bufio.NewScanner(bytes.NewReader(data))
	scanner.Buffer(make([]byte, 64*1024), maxTranscriptLine)
	for scanner.Scan() {
		line := bytes.TrimSpace(scanner.Bytes())
		if len(line) == 0 {
			continue
		}
		var entry Entry
		if json.Unmarshal(line, &entry) != nil {
			continue
		}
		if entry.ID == "" && entry.Type == "" {
			continue
		}
		entries = append(entries, entry)
	}
	if err := scanner.Err(); err != nil {
		return nil, fmt.Errorf("scan vibe transcript: %w", err)
	}
	return entries, nil
}

// atomicWriteFile writes data to path via a temp file and rename, so a crash
// mid-write cannot leave a partial transcript behind.
func atomicWriteFile(path string, data []byte, mode os.FileMode) error {
	tmp, err := os.CreateTemp(filepath.Dir(path), ".vibe-write-*")
	if err != nil {
		return err
	}
	tmpName := tmp.Name()
	defer os.Remove(tmpName)
	if err := tmp.Chmod(mode); err != nil {
		return errors.Join(err, tmp.Close())
	}
	if _, err := tmp.Write(data); err != nil {
		return errors.Join(err, tmp.Close())
	}
	if err := tmp.Close(); err != nil {
		return err
	}
	return os.Rename(tmpName, path)
}

