package vibe

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"time"

	"github.com/entireio/external-agents/agents/entire-agent-mistral-vibe/internal/protocol"
)

const (
	fetchTimeout = 20 * time.Second
	// freshWindow lets prepare-transcript skip a fetch when the turn-end hook
	// stored the transcript a moment ago.
	freshWindow = 3 * time.Second
)

// refresh fetches the session from Vibe and stores it at sessionRef as one
// history entry per line. Hook notices are left out. It never replaces a
// stored transcript with an empty one.
func (a *Agent) refresh(sessionRef, sessionID string) (*Snapshot, error) {
	if strings.TrimSpace(sessionRef) == "" || strings.TrimSpace(sessionID) == "" {
		return nil, errors.New("session id and session ref are required")
	}
	fetcher := a.Fetcher
	if fetcher == nil {
		fetcher = &AppServerFetcher{}
	}
	ctx, cancel := context.WithTimeout(context.Background(), fetchTimeout)
	defer cancel()
	snapshot, err := fetcher.FetchSession(ctx, sessionID, protocol.RepoRoot())
	if err != nil {
		return nil, err
	}

	existing, _ := os.ReadFile(sessionRef)
	lines, err := buildLines(snapshot, existing)
	if err != nil {
		return nil, err
	}
	if len(lines) == 0 {
		return snapshot, nil
	}
	if err := os.MkdirAll(filepath.Dir(sessionRef), 0o750); err != nil {
		return nil, err
	}
	if err := atomicWriteFile(sessionRef, encodeLines(lines), 0o600); err != nil {
		return nil, err
	}
	return snapshot, nil
}

// buildLines turns a snapshot into transcript lines. The last line gets the
// current usage and model; lines that carried a snapshot in the previous
// transcript keep it, so per-turn token deltas survive a refresh.
func buildLines(snapshot *Snapshot, existing []byte) ([]json.RawMessage, error) {
	previous := map[string]json.RawMessage{}
	for _, line := range bytes.Split(existing, []byte("\n")) {
		var probe struct {
			ID   string          `json:"id"`
			Meta json.RawMessage `json:"entire"`
		}
		if json.Unmarshal(line, &probe) == nil && probe.ID != "" && len(probe.Meta) > 0 {
			previous[probe.ID] = probe.Meta
		}
	}

	type kept struct {
		id     string
		fields map[string]json.RawMessage
	}
	entries := make([]kept, 0, len(snapshot.Entries))
	for _, raw := range snapshot.Entries {
		var fields map[string]json.RawMessage
		if json.Unmarshal(raw, &fields) != nil {
			continue
		}
		var id, entryType string
		_ = json.Unmarshal(fields["id"], &id)
		_ = json.Unmarshal(fields["type"], &entryType)
		if entryType == EntryNotice || entryType == "" {
			continue
		}
		// Never let a history entry supply its own snapshot.
		delete(fields, metaKey)
		if meta, ok := previous[id]; ok {
			fields[metaKey] = meta
		}
		entries = append(entries, kept{id: id, fields: fields})
	}

	if len(entries) > 0 && (snapshot.Usage != nil || snapshot.Model != "") {
		meta, err := json.Marshal(EntryMeta{Usage: snapshot.Usage, Model: snapshot.Model})
		if err != nil {
			return nil, err
		}
		entries[len(entries)-1].fields[metaKey] = meta
	}

	lines := make([]json.RawMessage, 0, len(entries))
	for _, entry := range entries {
		line, err := json.Marshal(entry.fields)
		if err != nil {
			return nil, err
		}
		lines = append(lines, line)
	}
	return lines, nil
}

// PrepareTranscript brings the stored transcript up to date. A failed refresh
// is an error only when there is nothing stored: an older transcript is still
// worth checkpointing, and Vibe may simply not be installed on this machine.
func (a *Agent) PrepareTranscript(sessionRef string) error {
	if strings.TrimSpace(sessionRef) == "" {
		return errors.New("session_ref is required")
	}
	info, statErr := os.Stat(sessionRef)
	hasContent := statErr == nil && info.Size() > 0
	if hasContent && time.Since(info.ModTime()) < freshWindow {
		return nil
	}
	sessionID := sessionIDFromRef(sessionRef)
	if sessionID == "" {
		return nil
	}
	if _, err := a.refresh(sessionRef, sessionID); err != nil {
		if hasContent {
			fmt.Fprintf(os.Stderr, "entire-agent-%s: transcript not refreshed: %v\n", agentName, err)
			return nil
		}
		return fmt.Errorf("refresh transcript: %w", err)
	}
	return nil
}

func (a *Agent) ReadSession(input *protocol.HookInputJSON) (protocol.AgentSessionJSON, error) {
	var sessionID, sessionRef string
	if input != nil {
		sessionID = input.SessionID
		sessionRef = input.SessionRef
		if sessionRef == "" && sessionID != "" {
			sessionRef = transcriptPath(sessionID)
		}
	}
	if sessionRef == "" {
		return protocol.AgentSessionJSON{}, errors.New("session_ref or session_id is required")
	}
	data, err := os.ReadFile(sessionRef)
	if err != nil {
		return protocol.AgentSessionJSON{}, err
	}
	entries, err := decodeTranscript(data)
	if err != nil {
		return protocol.AgentSessionJSON{}, err
	}
	if sessionID == "" {
		for _, entry := range entries {
			if entry.SessionID != "" {
				sessionID = entry.SessionID
				break
			}
		}
	}
	if sessionID == "" {
		sessionID = sessionIDFromRef(sessionRef)
	}
	return protocol.AgentSessionJSON{
		SessionID:     sessionID,
		AgentName:     agentName,
		RepoPath:      protocol.RepoRoot(),
		SessionRef:    sessionRef,
		StartTime:     startTime(entries).Format(time.RFC3339),
		NativeData:    data,
		ModifiedFiles: modifiedFiles(entries),
		NewFiles:      []string{},
		DeletedFiles:  []string{},
	}, nil
}

func startTime(entries []Entry) time.Time {
	for _, entry := range entries {
		if t := entry.createdTime(); !t.IsZero() {
			return t
		}
	}
	return time.Now().UTC()
}

// WriteSession restores Entire's copy of the transcript. It does not recreate a
// Vibe session, so `vibe --resume` only works where Vibe still has the original.
func (a *Agent) WriteSession(session protocol.AgentSessionJSON) error {
	if session.SessionRef == "" {
		return errors.New("session_ref is required")
	}
	if err := os.MkdirAll(filepath.Dir(session.SessionRef), 0o700); err != nil {
		return err
	}
	return atomicWriteFile(session.SessionRef, session.NativeData, 0o600)
}

func (a *Agent) ReadTranscript(sessionRef string) ([]byte, error) {
	return os.ReadFile(sessionRef)
}

func (a *Agent) ChunkTranscript(content []byte, maxSize int) ([][]byte, error) {
	if maxSize <= 0 {
		return nil, fmt.Errorf("max-size must be positive, got %d", maxSize)
	}
	var chunks [][]byte
	for len(content) > 0 {
		end := min(maxSize, len(content))
		chunks = append(chunks, content[:end])
		content = content[end:]
	}
	return chunks, nil
}

func (a *Agent) ReassembleTranscript(chunks [][]byte) ([]byte, error) {
	var data []byte
	for _, chunk := range chunks {
		data = append(data, chunk...)
	}
	return data, nil
}

func readEntries(path string) ([]Entry, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	return decodeTranscript(data)
}

// GetTranscriptPosition returns the number of stored entries. Positions are
// entry (line) indexes, the unit Entire uses to scope a checkpoint.
func (a *Agent) GetTranscriptPosition(path string) (int, error) {
	entries, err := readEntries(path)
	if err != nil {
		if os.IsNotExist(err) {
			return 0, nil
		}
		return 0, err
	}
	return len(entries), nil
}

func (a *Agent) ExtractModifiedFiles(path string, offset int) ([]string, int, error) {
	entries, err := readEntries(path)
	if err != nil {
		return nil, 0, err
	}
	return modifiedFiles(fromOffset(entries, offset)), len(entries), nil
}

func (a *Agent) ExtractPrompts(sessionRef string, offset int) ([]string, error) {
	entries, err := readEntries(sessionRef)
	if err != nil {
		return nil, err
	}
	prompts := []string{}
	for _, entry := range fromOffset(entries, offset) {
		if entry.Type != EntryMessage || entry.Role != RoleUser {
			continue
		}
		if text := entry.text(); text != "" {
			prompts = append(prompts, text)
		}
	}
	return prompts, nil
}

func (a *Agent) ExtractSummary(sessionRef string) (string, bool, error) {
	entries, err := readEntries(sessionRef)
	if err != nil {
		return "", false, err
	}
	for i := len(entries) - 1; i >= 0; i-- {
		entry := entries[i]
		if entry.Type != EntryMessage || entry.Role != RoleAssistant {
			continue
		}
		if text := entry.text(); text != "" {
			return text, true, nil
		}
	}
	return "", false, nil
}

// CalculateTokens reports usage for the entries from offset on. Vibe only
// exposes a running session total, so the figure is the difference between
// the last snapshot in range and the last snapshot before it. Snapshots are
// taken when a turn ends, so the range lines up with turns.
func (a *Agent) CalculateTokens(data []byte, offset int) (protocol.TokenUsageResponse, error) {
	entries, err := decodeTranscript(data)
	if err != nil {
		return protocol.TokenUsageResponse{}, err
	}
	if offset < 0 {
		offset = 0
	}
	var before, after *TokenUsage
	var usage protocol.TokenUsageResponse
	for i, entry := range entries {
		if i >= offset && (entry.Type == EntryEffect || (entry.Type == EntryMessage && entry.Role == RoleAssistant)) {
			usage.APICallCount++
		}
		if entry.Meta == nil || entry.Meta.Usage == nil {
			continue
		}
		if i < offset {
			before = entry.Meta.Usage
		} else {
			after = entry.Meta.Usage
		}
	}
	if after == nil {
		return usage, nil
	}
	if before == nil {
		before = &TokenUsage{}
	}
	cached := max(after.CachedInputTokens-before.CachedInputTokens, 0)
	input := max(after.InputTokens-before.InputTokens, 0)
	usage.CacheReadTokens = cached
	usage.InputTokens = max(input-cached, 0)
	usage.OutputTokens = max(after.OutputTokens-before.OutputTokens, 0)
	return usage, nil
}

// latestModel returns the model recorded by the most recent refresh.
func latestModel(entries []Entry) string {
	for i := len(entries) - 1; i >= 0; i-- {
		if entries[i].Meta != nil && entries[i].Meta.Model != "" {
			return entries[i].Meta.Model
		}
	}
	return ""
}

func fromOffset(entries []Entry, offset int) []Entry {
	if offset < 0 {
		offset = 0
	}
	if offset >= len(entries) {
		return nil
	}
	return entries[offset:]
}

func modifiedFiles(entries []Entry) []string {
	root := protocol.RepoRoot()
	seen := map[string]bool{}
	for _, entry := range entries {
		if !isFileChange(entry) {
			continue
		}
		var paths []string
		if entry.State != nil {
			paths = append(paths, pathsFromJSON(entry.State.Output)...)
		}
		if len(paths) == 0 {
			paths = pathsFromJSON(entry.Detail.Input)
		}
		for _, path := range paths {
			if path = repoRelative(root, path); path != "" {
				seen[path] = true
			}
		}
	}
	files := make([]string, 0, len(seen))
	for file := range seen {
		files = append(files, file)
	}
	sort.Strings(files)
	return files
}

// isFileChange reports whether an entry is a tool call that changed a file and
// was not refused, skipped or failed.
func isFileChange(entry Entry) bool {
	if entry.Type != EntryEffect || entry.Detail == nil {
		return false
	}
	if entry.State != nil {
		switch entry.State.Status {
		case "failed", "cancelled", "skipped", "blocked":
			return false
		}
	}
	switch entry.Detail.Kind {
	case "file_write", "file_edit", "file_change":
		return true
	}
	name := entry.Detail.ToolName
	if i := strings.LastIndex(name, "."); i >= 0 {
		name = name[i+1:]
	}
	switch strings.ToLower(name) {
	case "write_file", "search_replace", "edit", "edit_file", "apply_patch", "delete_file", "move_file":
		return true
	}
	return false
}

var filePathKeys = []string{"filePath", "file_path", "path"}

func pathsFromJSON(raw json.RawMessage) []string {
	var obj map[string]json.RawMessage
	if len(raw) == 0 || json.Unmarshal(raw, &obj) != nil {
		return nil
	}
	var paths []string
	for _, key := range filePathKeys {
		var value string
		if json.Unmarshal(obj[key], &value) == nil && strings.TrimSpace(value) != "" {
			paths = append(paths, strings.TrimSpace(value))
		}
	}
	return paths
}

// repoRelative returns path relative to the repository when it is inside it,
// and unchanged otherwise.
func repoRelative(root, path string) string {
	if !filepath.IsAbs(path) || root == "" {
		return filepath.ToSlash(filepath.Clean(path))
	}
	for _, base := range []string{root, resolved(root)} {
		for _, candidate := range []string{path, resolved(path)} {
			rel, err := filepath.Rel(base, candidate)
			if err == nil && rel != "." && !strings.HasPrefix(rel, "..") {
				return filepath.ToSlash(rel)
			}
		}
	}
	return path
}

// resolved follows symlinks in the longest existing prefix of path, so a file
// under /var and a root under /private/var still compare as inside.
func resolved(path string) string {
	if real, err := filepath.EvalSymlinks(path); err == nil {
		return real
	}
	dir, file := filepath.Split(filepath.Clean(path))
	if dir == "" || dir == path {
		return path
	}
	return filepath.Join(resolved(filepath.Clean(dir)), file)
}

package vibe

import (
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"regexp"
	"strings"
	"time"

	"github.com/entireio/external-agents/agents/entire-agent-mistral-vibe/internal/protocol"
)

// Hook names passed as `entire hooks mistral-vibe <hook>`.
const (
	HookNameSessionStart = "session-start"
	HookNamePreAgent     = "pre-agent"
	HookNameNotification = "notification"
	HookNameSessionEnd   = "session-end"
)

const (
	notificationTurnCompleted = "turn_completed"
	notificationTurnFailed    = "turn_failed"
)

// hookPayload is the JSON Vibe writes to a hook's stdin. Every event carries
// the session fields; the rest depend on hook_event_name.
type hookPayload struct {
	SessionID        string `json:"session_id"`
	ParentSessionID  string `json:"parent_session_id"`
	Source           string `json:"source"`
	Model            string `json:"model"`
	Prompt           string `json:"prompt"`
	NotificationType string `json:"notification_type"`
	Message          string `json:"message"`
}

// ParseHook maps a Vibe hook payload to an Entire lifecycle event.
//
// Turn end comes from the turn_completed / turn_failed notifications, not from
// post_agent: post_agent fires on a candidate answer that a hook can still
// reject, and the reply is not in the session history until the turn is
// accepted.
func (a *Agent) ParseHook(hookName string, input []byte) (*protocol.EventJSON, error) {
	if len(strings.TrimSpace(string(input))) == 0 {
		return nil, nil
	}
	var raw hookPayload
	if err := json.Unmarshal(input, &raw); err != nil {
		return nil, fmt.Errorf("parse %s payload: %w", hookName, err)
	}
	// Subagents are part of the parent's turn; their own events are not turns.
	if raw.SessionID == "" || raw.ParentSessionID != "" {
		return nil, nil
	}

	sessionRef := transcriptPath(raw.SessionID)
	event := &protocol.EventJSON{
		SessionID:  raw.SessionID,
		SessionRef: sessionRef,
		Timestamp:  time.Now().UTC().Format(time.RFC3339),
	}

	switch hookName {
	case HookNameSessionStart:
		event.Type = 1
		event.Model = raw.Model
		// A resumed or forked session already has history; store it so the
		// first turn's checkpoint starts after it.
		if raw.Source == "resume" || raw.Source == "fork" {
			a.refreshBestEffort(sessionRef, raw.SessionID)
		}
		if err := ensureTranscriptFile(sessionRef); err != nil {
			return nil, err
		}

	case HookNamePreAgent:
		event.Type = 2
		event.Prompt = raw.Prompt
		if err := ensureTranscriptFile(sessionRef); err != nil {
			return nil, err
		}

	case HookNameNotification:
		switch raw.NotificationType {
		case notificationTurnCompleted:
		case notificationTurnFailed:
			if raw.Message != "" {
				event.Metadata = map[string]string{"error": raw.Message}
			}
		default:
			return nil, nil
		}
		event.Type = 3
		if snapshot := a.refreshBestEffort(sessionRef, raw.SessionID); snapshot != nil {
			event.Model = snapshot.Model
		}
		if err := ensureTranscriptFile(sessionRef); err != nil {
			return nil, err
		}

	case HookNameSessionEnd:
		event.Type = 5
		a.refreshBestEffort(sessionRef, raw.SessionID)

	default:
		return nil, nil
	}
	return event, nil
}

// refreshBestEffort updates the stored transcript. A hook must not fail because
// Vibe's app server could not be reached; prepare-transcript tries again.
func (a *Agent) refreshBestEffort(sessionRef, sessionID string) *Snapshot {
	snapshot, err := a.refresh(sessionRef, sessionID)
	if err != nil {
		fmt.Fprintf(os.Stderr, "entire-agent-%s: transcript not refreshed: %v\n", agentName, err)
		return nil
	}
	return snapshot
}

// ensureTranscriptFile creates an empty transcript when none exists, so Entire
// can read a position before the first turn has produced any history.
func ensureTranscriptFile(sessionRef string) error {
	if _, err := os.Lstat(sessionRef); err == nil {
		return nil
	}
	if err := os.MkdirAll(filepath.Dir(sessionRef), 0o750); err != nil {
		return err
	}
	file, err := os.OpenFile(sessionRef, os.O_CREATE|os.O_WRONLY, 0o600)
	if err != nil {
		return err
	}
	return file.Close()
}

// --- hooks.toml ---

const (
	vibeDir   = ".vibe"
	hooksFile = ".vibe/hooks.toml"

	blockStart = "# >>> entire hooks: managed by `entire enable --agent mistral-vibe`, do not edit >>>"
	blockEnd   = "# <<< entire hooks <<<"
)

type hookEntry struct {
	name     string
	hookType string
	match    string
	hookName string
	timeout  int
}

// installedHooks are the Vibe hooks Entire needs. Tool hooks are not installed:
// tool calls are read from the session history instead, which keeps Entire out
// of the path of every tool call.
var installedHooks = []hookEntry{
	{name: "entire-session-start", hookType: "session_start", hookName: HookNameSessionStart, timeout: 60},
	{name: "entire-pre-agent", hookType: "pre_agent", match: "main", hookName: HookNamePreAgent, timeout: 60},
	{name: "entire-turn-completed", hookType: "notification", match: notificationTurnCompleted, hookName: HookNameNotification, timeout: 120},
	{name: "entire-turn-failed", hookType: "notification", match: notificationTurnFailed, hookName: HookNameNotification, timeout: 120},
	{name: "entire-session-end", hookType: "session_end", hookName: HookNameSessionEnd, timeout: 120},
}

// hookCommand always names the `entire` binary on PATH and never fails or
// prints: Vibe treats non-JSON stdout or a non-zero exit as a hook failure and
// shows a warning on every event. An absolute path would break the committed
// file on any other machine.
func hookCommand(hookName string) string {
	return fmt.Sprintf("if command -v entire >/dev/null 2>&1; then entire hooks %s %s >/dev/null 2>&1 || true; fi", agentName, hookName)
}

func renderBlock() string {
	var b strings.Builder
	b.WriteString(blockStart + "\n")
	for _, hook := range installedHooks {
		b.WriteString("[[hooks]]\n")
		fmt.Fprintf(&b, "name = %q\n", hook.name)
		fmt.Fprintf(&b, "type = %q\n", hook.hookType)
		if hook.match != "" {
			fmt.Fprintf(&b, "match = %q\n", hook.match)
		}
		fmt.Fprintf(&b, "command = %q\n", hookCommand(hook.hookName))
		fmt.Fprintf(&b, "timeout = %d.0\n", hook.timeout)
		b.WriteString("description = \"Entire session tracking\"\n\n")
	}
	b.WriteString(blockEnd + "\n")
	return b.String()
}

// splitBlock returns the text before and after the managed block, and whether
// a complete block was found.
func splitBlock(content string) (before, block, after string, found bool) {
	start := strings.Index(content, blockStart)
	if start < 0 {
		return content, "", "", false
	}
	end := strings.Index(content[start:], blockEnd)
	if end < 0 {
		return content, "", "", false
	}
	end += start + len(blockEnd)
	if end < len(content) && content[end] == '\n' {
		end++
	}
	return content[:start], content[start:end], content[end:], true
}

// inlineHooksKey matches `hooks = [...]`, which cannot coexist with the
// `[[hooks]]` tables Entire appends.
var inlineHooksKey = regexp.MustCompile(`(?m)^\s*hooks\s*=`)

func readHooksFile(path string) (string, error) {
	info, err := os.Lstat(path)
	if os.IsNotExist(err) {
		return "", nil
	}
	if err != nil {
		return "", err
	}
	if !info.Mode().IsRegular() {
		return "", fmt.Errorf("refusing to edit %s: not a regular file", path)
	}
	data, err := os.ReadFile(path)
	if err != nil {
		return "", err
	}
	return string(data), nil
}

// InstallHooks adds Entire's hooks to .vibe/hooks.toml, leaving the user's own
// entries untouched. Vibe only loads project hooks in a trusted folder.
func (a *Agent) InstallHooks(_ bool, force bool) (int, error) {
	root := protocol.RepoRoot()
	path := filepath.Join(root, hooksFile)
	content, err := readHooksFile(path)
	if err != nil {
		return 0, err
	}

	want := renderBlock()
	before, block, after, found := splitBlock(content)
	if found && block == want && !force {
		return 0, nil
	}
	if inlineHooksKey.MatchString(before + after) {
		return 0, fmt.Errorf("%s defines hooks as an inline array; convert it to [[hooks]] tables before installing", path)
	}

	var updated string
	if found {
		updated = before + want + after
	} else {
		updated = content
		if updated != "" && !strings.HasSuffix(updated, "\n") {
			updated += "\n"
		}
		if updated != "" {
			updated += "\n"
		}
		updated += want
	}

	if err := os.MkdirAll(filepath.Join(root, vibeDir), 0o750); err != nil {
		return 0, fmt.Errorf("create %s: %w", vibeDir, err)
	}
	if err := atomicWriteFile(path, []byte(updated), 0o644); err != nil {
		return 0, fmt.Errorf("write %s: %w", path, err)
	}
	return len(installedHooks), nil
}

// UninstallHooks removes only Entire's block. The file and .vibe directory are
// removed when nothing else is left in them.
func (a *Agent) UninstallHooks() error {
	root := protocol.RepoRoot()
	path := filepath.Join(root, hooksFile)
	content, err := readHooksFile(path)
	if err != nil {
		return err
	}
	before, _, after, found := splitBlock(content)
	if !found {
		return nil
	}
	remaining := strings.TrimRight(before, "\n")
	if remaining != "" {
		remaining += "\n"
	}
	if strings.TrimSpace(after) != "" {
		if remaining != "" {
			remaining += "\n"
		}
		remaining += strings.TrimLeft(after, "\n")
	}

	if strings.TrimSpace(remaining) == "" {
		if err := os.Remove(path); err != nil && !os.IsNotExist(err) {
			return err
		}
		dir := filepath.Join(root, vibeDir)
		if entries, err := os.ReadDir(dir); err == nil && len(entries) == 0 {
			_ = os.Remove(dir)
		}
		return nil
	}
	return atomicWriteFile(path, []byte(remaining), 0o644)
}

func hooksInstalled() (bool, error) {
	content, err := readHooksFile(filepath.Join(protocol.RepoRoot(), hooksFile))
	if err != nil {
		return false, err
	}
	_, block, _, found := splitBlock(content)
	if !found {
		return false, nil
	}
	for _, hook := range installedHooks {
		if !strings.Contains(block, fmt.Sprintf("name = %q", hook.name)) {
			return false, nil
		}
	}
	return true, nil
}

// AreHooksInstalled reports false when the state cannot be read; use
// HooksInstalledState when "unknown" must not be mistaken for "none".
func (a *Agent) AreHooksInstalled() bool {
	installed, _ := hooksInstalled()
	return installed
}

// HooksInstalledState returns an error when the hooks file exists but cannot
// be read, so the caller can report the state as unknown.
func (a *Agent) HooksInstalledState() (bool, error) {
	installed, err := hooksInstalled()
	if err != nil {
		return false, errors.Join(errors.New("cannot read hooks state"), err)
	}
	return installed, nil
}

package vibe

import (
	"bytes"
	"encoding/base64"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"strings"
	"time"

	"github.com/entireio/external-agents/agents/entire-agent-mistral-vibe/internal/protocol"
)

const compactTranscriptCLIVersion = "unknown"

type compactLine struct {
	V          int    `json:"v"`
	Agent      string `json:"agent"`
	CLIVersion string `json:"cli_version"`
	Type       string `json:"type"`
	TS         string `json:"ts,omitempty"`
	ID         string `json:"id,omitempty"`
	Content    any    `json:"content"`
}

type compactUserText struct {
	Text string `json:"text"`
}

type compactText struct {
	Type string `json:"type"`
	Text string `json:"text"`
}

type compactToolUse struct {
	Type   string             `json:"type"`
	ID     string             `json:"id,omitempty"`
	Name   string             `json:"name"`
	Input  any                `json:"input"`
	Result *compactToolResult `json:"result,omitempty"`
}

type compactToolResult struct {
	Output string `json:"output"`
	Status string `json:"status"`
}

// CompactTranscript converts stored history into Entire Transcript Format.
// sessionRef may be a temp file holding a slice of the transcript.
func (a *Agent) CompactTranscript(sessionRef string) (protocol.CompactTranscriptResponse, error) {
	data, err := os.ReadFile(sessionRef)
	if err != nil {
		return protocol.CompactTranscriptResponse{}, fmt.Errorf("failed to read transcript: %w", err)
	}
	compacted, err := compactTranscriptBytes(data)
	if err != nil {
		return protocol.CompactTranscriptResponse{}, err
	}
	return protocol.CompactTranscriptResponse{Transcript: base64.StdEncoding.EncodeToString(compacted)}, nil
}

// compactTranscriptBytes emits one line per user message, assistant message
// and tool call. Reasoning is dropped.
func compactTranscriptBytes(data []byte) ([]byte, error) {
	entries, err := decodeTranscript(data)
	if err != nil {
		return nil, err
	}
	cliVersion := compactTranscriptCLIVersion
	if version := strings.TrimSpace(os.Getenv("ENTIRE_CLI_VERSION")); version != "" {
		cliVersion = version
	}

	var buf bytes.Buffer
	for _, entry := range entries {
		line := compactLine{V: 1, Agent: agentName, CLIVersion: cliVersion, TS: entryTimestamp(entry)}
		switch {
		case entry.Type == EntryMessage && entry.Role == RoleUser:
			text := entry.text()
			if text == "" {
				continue
			}
			line.Type = "user"
			line.Content = []compactUserText{{Text: text}}
		case entry.Type == EntryMessage && entry.Role == RoleAssistant:
			text := entry.text()
			if text == "" {
				continue
			}
			line.Type = "assistant"
			line.ID = entry.ID
			line.Content = []any{compactText{Type: "text", Text: text}}
		case entry.Type == EntryEffect:
			line.Type = "assistant"
			line.ID = entry.ID
			line.Content = []any{compactTool(entry)}
		default:
			continue
		}
		encoded, err := json.Marshal(line)
		if err != nil {
			return nil, err
		}
		buf.Write(encoded)
		buf.WriteByte('\n')
	}
	if buf.Len() == 0 {
		return nil, errors.New("compact transcript produced no output")
	}
	return buf.Bytes(), nil
}

func compactTool(entry Entry) compactToolUse {
	tool := compactToolUse{Type: "tool_use", ID: entry.ID, Name: entry.Title, Input: map[string]any{}}
	if entry.Detail != nil {
		if entry.Detail.ToolName != "" {
			tool.Name = entry.Detail.ToolName
		}
		if len(entry.Detail.Input) > 0 {
			var input any
			if json.Unmarshal(entry.Detail.Input, &input) == nil && input != nil {
				tool.Input = input
			}
		}
	}
	if entry.State == nil {
		return tool
	}
	status := "success"
	output := entry.State.OutputText
	if output == "" && len(entry.State.Output) > 0 && string(entry.State.Output) != "null" {
		output = string(entry.State.Output)
	}
	switch entry.State.Status {
	case "failed", "cancelled", "skipped", "blocked":
		status = "error"
		if output == "" && len(entry.State.Error) > 0 && string(entry.State.Error) != "null" {
			output = string(entry.State.Error)
		}
	case "completed":
	default:
		// Still pending or running: there is no result yet.
		return tool
	}
	tool.Result = &compactToolResult{Output: output, Status: status}
	return tool
}

func entryTimestamp(entry Entry) string {
	if t := entry.createdTime(); !t.IsZero() {
		return t.Format(time.RFC3339)
	}
	return ""
}

